const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Brazil geometry
  const brazil = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017').filter(ee.Filter.eq('country_na', 'Brazil'));

  // 2. Define date ranges
  const start2007 = '2007-01-01';
  const end2007 = '2007-12-31';
  const start2019 = '2019-01-01';
  const end2019 = '2019-12-31';

  // 3. Load MODIS Thermal Anomalies (fire detection dataset)
  const mod14a1 = ee.ImageCollection('MODIS/006/MOD14A1');

  // Filter for 2007
  const fires2007 = mod14a1
    .filterDate(start2007, end2007)
    .filterBounds(brazil);

  // Filter for 2019
  const fires2019 = mod14a1
    .filterDate(start2019, end2019)
    .filterBounds(brazil);

  print('Data Collection Check:');
  print('2007 Images: ' + fires2007.size().getInfo());
  print('2019 Images: ' + fires2019.size().getInfo());

  // Check for empty collections
  if (fires2007.size().getInfo() === 0) {
    print('No data for 2007.');
    print('C1');
    return;
  }
  if (fires2019.size().getInfo() === 0) {
    print('No data for 2019.');
    print('C1');
    return;
  }

  // 4. Count fire detections (FireMask band, values > 0 indicate fire)
  // Use the 'FireMask' band: 0=no fire, 1-8=fire with different confidence levels
  const countFires2007 = fires2007
    .select('FireMask')
    .map(function(img) {
      return img.gt(0).rename('fire_count');
    })
    .reduce(ee.Reducer.sum());

  const countFires2019 = fires2019
    .select('FireMask')
    .map(function(img) {
      return img.gt(0).rename('fire_count');
    })
    .reduce(ee.Reducer.sum());

  // 5. Get fire counts in Brazil
  const fireCount2007 = countFires2007.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: brazil,
    scale: 1000,
    maxPixels: 1e9
  }).get('fire_count_sum').getInfo();

  const fireCount2019 = countFires2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: brazil,
    scale: 1000,
    maxPixels: 1e9
  }).get('fire_count_sum').getInfo();

  print('Fire Detection Results:');
  print('2007 Fire Detections: ' + fireCount2007);
  print('2019 Fire Detections: ' + fireCount2019);

  // 6. Validation
  if (fireCount2007 === null || fireCount2019 === null) {
    print('C3');
    return;
  }

  if (fireCount2007 === 0 && fireCount2019 === 0) {
    print('C2');
    return;
  }

  // 7. Compare: Were there fewer detections in 2019 than 2007?
  if (fireCount2019 < fireCount2007) {
    print('A');
  } else {
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
